$candidacy_workbook$::jsonb) AS x(
 id uuid, new_person uuid, year integer, period integer, number integer, district text, source_key text,
 party text, name text, share numeric, votes bigint, anchors uuid[], current uuid[], issues text[], sources jsonb, roster jsonb
);

-- Migration consumes source nomination IDs and confirmed connection/person IDs.
-- No mandate rows or electoral dates are created by the workbook.
DO $import$
DECLARE
 x record;
 p_id uuid;
 d_id uuid;
 faction text;
 ballot text;
 target_person uuid;
 candidates uuid[];
 identities uuid[];
 connections uuid[];
 target_candidacy uuid;
 outcome_at_election text;
 original_mandate_id uuid;
 nomination_url text;
 source_note text;
 import_status text;
 existing public.election_history_candidacies;
 digest constant text := 'd5fa9da0aadaee070a98ee6c70f32a51264bc361bd289643c03ed415178d12ed';
BEGIN
 PERFORM set_config('app.assembling_election_history','on',true);
 FOR x IN SELECT * FROM candidate_workbook_rows ORDER BY period,number,party,id LOOP
  IF EXISTS(SELECT 1 FROM public.election_history_candidate_workbook_audit a
            WHERE a.workbook_sha256=digest AND a.source_id=x.id) THEN CONTINUE; END IF;
  target_candidacy:=NULL;
  BEGIN
   SELECT id INTO p_id FROM public.election_history_periods WHERE number=x.period AND election_year=x.year FOR UPDATE;
   IF p_id IS NULL THEN RAISE EXCEPTION 'Wahlperiode fehlt'; END IF;
   SELECT id INTO d_id FROM public.election_history_districts d WHERE d.period_id=p_id AND
    (CASE WHEN x.year=1952 THEN d.geometry_source_key=x.source_key ELSE d.district_number=x.number END);
   IF d_id IS NULL AND x.year<>1952 THEN
    SELECT array_agg(d.id) INTO candidates
    FROM public.election_history_districts d WHERE d.period_id=p_id AND d.district_number IS NULL
     AND d.number_label IN (x.number::text,lpad(x.number::text,2,'0'))
     AND lower(btrim(d.name))=lower(btrim(x.district));
    IF cardinality(candidates)=1 THEN d_id:=candidates[1]; END IF;
   END IF;
   IF d_id IS NULL THEN RAISE EXCEPTION 'Historischer Wahlkreis fehlt'; END IF;
   faction:=public.resolve_history_faction(x.party);
   IF faction IS NULL THEN RAISE EXCEPTION 'Partei fehlt im Katalog'; END IF;
   ballot:=CASE WHEN x.year>=2026 THEN 'first_vote' ELSE 'candidate' END;

   SELECT array_agg(DISTINCT coalesce(cp.person_id,m.person_id))
    FILTER (WHERE coalesce(cp.person_id,m.person_id) IS NOT NULL),
    array_agg(DISTINCT m.connection_id) FILTER (WHERE m.connection_id IS NOT NULL)
    INTO identities,connections
   FROM public.election_history_mandates m
   LEFT JOIN public.election_history_connection_people cp ON cp.connection_id=m.connection_id
   WHERE m.id=ANY(x.anchors);
   IF cardinality(identities)>1 THEN RAISE EXCEPTION 'Mehrere bestätigte Personen-IDs'; END IF;
   target_person:=identities[1];
   IF cardinality(connections)>1 OR EXISTS(
    SELECT 1 FROM public.election_history_mandates m
    JOIN public.election_history_connection_people cp ON cp.connection_id=m.connection_id
    WHERE m.id=ANY(x.anchors) AND m.person_id IS NOT NULL AND m.person_id<>cp.person_id
   ) THEN RAISE EXCEPTION 'Mehrere oder widersprüchliche Mandatshistorien'; END IF;
   IF target_person IS NULL AND cardinality(x.anchors)>0 AND connections[1] IS NULL THEN
    RAISE EXCEPTION 'Mandatsbeleg ohne bestätigte Personenverbindung';
   END IF;
   IF EXISTS(SELECT 1 FROM unnest(x.issues) issue WHERE issue<>'Mandat unter gleichem Namen, Identität offen') THEN
    RAISE EXCEPTION '%',array_to_string(x.issues,'; ');
   END IF;
   -- A roster entry confirms a specific first-vote nomination. Reuse its
   -- connection only when the register has also established the person binding.
   IF x.year=2026 AND jsonb_typeof(x.roster)='object' THEN
    SELECT array_agg(DISTINCT cp.person_id) INTO identities
    FROM public.election_history_state_list_entries e
    JOIN public.election_history_state_lists l ON l.id=e.list_id
    JOIN public.election_history_connection_people cp ON cp.connection_id=e.connection_id
    WHERE l.period_id=p_id AND l.party=faction AND e.candidacy_role='direct'
     AND e.position=(x.roster->>'position')::integer AND e.district_number=x.number
     AND public.history_list_person_key(e.person_name)=public.history_list_person_key(x.name);
    IF cardinality(identities)>1 OR (target_person IS NOT NULL AND identities[1]<>target_person) THEN
     RAISE EXCEPTION 'Mandats- und Landeslistenverbindung widersprechen sich';
    END IF;
    target_person:=coalesce(target_person,identities[1]);
   END IF;
   IF target_person IS NULL AND cardinality(x.issues)>0 THEN RAISE EXCEPTION '%',array_to_string(x.issues,'; '); END IF;

   SELECT array_agg(c.id) INTO candidates FROM public.election_history_candidacies c
   WHERE c.period_id=p_id AND c.district_id=d_id AND c.ballot_type=ballot AND c.party=faction;
   IF cardinality(candidates)>1 THEN RAISE EXCEPTION 'Mehrere bestehende Kandidaturen für diesen Wahlvorschlag'; END IF;
   SELECT * INTO existing FROM public.election_history_candidacies WHERE id=candidates[1];
   IF existing.id IS NOT NULL AND (
    (target_person IS NOT NULL AND existing.person_id<>target_person) OR
    (target_person IS NULL AND NOT EXISTS(SELECT 1 FROM public.election_history_people person WHERE person.id=existing.person_id
      AND public.history_list_person_key(person.name)=public.history_list_person_key(x.name)))) THEN
    RAISE EXCEPTION 'Bestehende Kandidatur gehört zu einer anderen Person';
   END IF;
   IF existing.outcome='direct' THEN RAISE EXCEPTION 'Bestehendes Direktmandat widerspricht der Quelle'; END IF;
   IF existing.id IS NULL AND EXISTS(SELECT 1 FROM public.election_history_candidacies c
    WHERE c.period_id=p_id AND c.district_id=d_id AND c.person_id=target_person) THEN
    RAISE EXCEPTION 'Person ist in diesem Wahlkreis bereits mit abweichender Partei oder Stimmenart erfasst';
   END IF;
   target_person:=coalesce(target_person,existing.person_id,x.new_person);
   IF existing.id IS NULL THEN
    INSERT INTO public.election_history_people(id,name,source_url)
     VALUES(target_person,x.name,x.sources->0->>'source') ON CONFLICT(id) DO NOTHING;
   END IF;
   IF connections[1] IS NOT NULL THEN
    INSERT INTO public.election_history_connection_people(connection_id,person_id)
     VALUES(connections[1],target_person) ON CONFLICT(connection_id) DO NOTHING;
   END IF;

   UPDATE public.election_history_mandates m SET person_id=target_person
   WHERE m.id=ANY(x.anchors) AND m.connection_id=connections[1] AND m.person_id IS NULL;

   SELECT m.id INTO original_mandate_id FROM public.election_history_mandates m
   WHERE m.period_id=p_id AND m.district_id=d_id AND m.id=ANY(x.current)
    AND m.person_id=target_person AND m.entry_type='election' AND m.mandate_type='list';
   outcome_at_election:=CASE
    WHEN original_mandate_id IS NOT NULL THEN 'list'
    WHEN existing.outcome='list' THEN 'list'
    WHEN EXISTS(SELECT 1 FROM public.election_history_mandates m
      WHERE m.period_id=p_id AND m.district_id=d_id AND m.person_id=target_person
        AND m.mandate_type='direct' AND m.entry_type='election') THEN 'direct'
    -- A statewide list mandate does not follow from the constituency result.
    WHEN x.year=2026 AND EXISTS(SELECT 1 FROM public.election_history_mandates m
      WHERE m.period_id=p_id AND m.person_id=target_person AND m.entry_type='election' AND m.mandate_type='list')
      THEN 'list'
    ELSE 'not_elected' END;
   IF outcome_at_election='direct' THEN RAISE EXCEPTION 'Bestehendes Direktmandat widerspricht der Quelle'; END IF;
   IF existing.outcome IN ('list','not_elected') AND existing.outcome<>outcome_at_election THEN
    RAISE EXCEPTION 'Vorhandener Wahlausgang widerspricht der Mandatszuordnung';
   END IF;
   IF jsonb_typeof(x.roster)='object' AND x.year=2026 THEN
    nomination_url:='https://im.baden-wuerttemberg.de/fileadmin/redaktion/m-im/intern/dateien/pdf/20260123_Kreiswahlvorschlaege_nach_70_Wahlkreisen_geordnet.pdf';
   ELSE
    nomination_url:=x.sources->0->>'source';
   END IF;
   source_note:=format('Arbeitsmappe SHA-256 %s, %s, Zeile %s. Ergebnisquelle: %s.',
    digest,x.sources->0->>'sheet',x.sources->0->>'row',coalesce(x.sources->0->>'result',x.sources->0->>'source','siehe Herkunftsprotokoll'));

   IF existing.id IS NULL THEN
    INSERT INTO public.election_history_candidacies
     (id,period_id,district_id,person_id,party,ballot_type,outcome,votes,vote_share,source_url,result_origin,result_notes)
    VALUES(x.id,p_id,d_id,target_person,faction,ballot,outcome_at_election,x.votes,x.share,nomination_url,'candidate_workbook',source_note);
    target_candidacy:=x.id;
    import_status:='added';
   ELSE
    target_candidacy:=existing.id;
    UPDATE public.election_history_candidacies c SET
     votes=coalesce(c.votes,x.votes),vote_share=coalesce(c.vote_share,x.share),
     outcome=CASE WHEN c.outcome='unknown' THEN outcome_at_election ELSE c.outcome END,
     source_url=coalesce(c.source_url,nomination_url),result_notes=coalesce(c.result_notes,source_note)
    WHERE c.id=target_candidacy AND (c.outcome='unknown' OR
      (c.votes IS NULL AND x.votes IS NOT NULL) OR (c.vote_share IS NULL AND x.share IS NOT NULL));
    import_status:=CASE WHEN (existing.votes IS NOT NULL AND x.votes IS NOT NULL AND existing.votes<>x.votes)
      OR (existing.vote_share IS NOT NULL AND x.share IS NOT NULL AND abs(existing.vote_share-x.share)>0.051)
      THEN 'existing_result_differs' ELSE 'existing' END;
   END IF;

   -- Succession is linked only where the workbook proves this candidate
   -- occupied the same nomination slot. Preserve all recorded dates and entry types.
   UPDATE public.election_history_mandates m SET candidacy_id=target_candidacy,person_id=target_person
   WHERE m.period_id=p_id AND m.district_id=d_id AND m.id=ANY(x.current)
    AND m.candidacy_id IS NULL AND (m.person_id IS NULL OR m.person_id=target_person)
    AND (m.entry_type='succession' OR m.id=original_mandate_id);
  EXCEPTION WHEN raise_exception OR integrity_constraint_violation THEN
   target_candidacy:=NULL;
   GET STACKED DIAGNOSTICS import_status=MESSAGE_TEXT;
  END;
  INSERT INTO public.election_history_candidate_workbook_audit
   VALUES(digest,x.id,target_candidacy,x.source_data,import_status);
 END LOOP;
 PERFORM set_config('app.assembling_election_history','',true);
END $import$;
CREATE OR REPLACE FUNCTION public.get_election_candidate_results(selected_period uuid, selected_district uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $function$
 WITH candidates AS (
  SELECT c.*, p.name AS person_name, lp.election_year, lp.number AS period_number,
   CASE WHEN c.party IN ('FDP/DVP','FDP') THEN 'FDP'
        WHEN upper(c.party) IN ('GRÜNE','BÜNDNIS 90/DIE GRÜNEN') THEN 'GRÜNE'
        WHEN upper(c.party)='AFD' THEN 'AfD' ELSE c.party END AS result_party
  FROM public.election_history_candidacies c
  JOIN public.election_history_periods lp ON lp.id=c.period_id AND lp.is_published
  JOIN public.election_history_districts d ON d.id=c.district_id AND d.period_id=c.period_id
  LEFT JOIN public.election_history_people p ON p.id=c.person_id
  WHERE c.period_id=$1 AND c.district_id=$2
 ), eligible AS (
  SELECT c.*, count(*) OVER (PARTITION BY result_party) AS party_candidates
  FROM candidates c
  WHERE (election_year<2026 AND ballot_type='candidate') OR (election_year>=2026 AND ballot_type='first_vote')
 ), rows AS (
  SELECT c.id AS candidacy_id,c.person_id,c.person_name,c.party,c.votes,c.vote_share,c.ballot_type,c.outcome,c.result_notes,c.source_url,
   (SELECT m.entry_type FROM public.election_history_mandates m
    WHERE m.person_id=c.person_id AND m.period_id=c.period_id
    ORDER BY m.entry_type LIMIT 1) AS mandate_entry_type,
   (SELECT min(lp.number) FROM public.election_history_mandates m
    JOIN public.election_history_periods lp ON lp.id=m.period_id AND lp.is_published
    WHERE m.person_id=c.person_id AND lp.number>c.period_number) AS next_mandate_period,
   CASE WHEN e.id IS NULL THEN 'ballot_mismatch'
        WHEN e.party_candidates<>1 THEN 'ambiguous'
        WHEN r.year IS NULL THEN 'missing' ELSE 'linked' END AS link_status,
   CASE WHEN r.year IS NOT NULL THEN jsonb_build_object(
    'ballot',r.ballot,'votes',r.votes,'share',r.share,'preliminary',r.preliminary,
    'data_release',r.data_release,'notes',r.notes) ELSE NULL END AS district_result
  FROM candidates c
  LEFT JOIN eligible e ON e.id=c.id
  LEFT JOIN public.election_analysis_versions v ON v.historical_district_id=c.district_id
   AND v.history_link_verified AND v.year=c.election_year
  LEFT JOIN public.election_analysis_years y ON y.year=v.year AND y.period_id=c.period_id AND y.is_published
  LEFT JOIN public.election_analysis_districts r ON r.year=y.year AND r.district_number=v.district_number
   AND r.party=c.result_party AND e.party_candidates=1
   AND r.ballot=CASE WHEN c.election_year<2026 THEN 'single' ELSE 'first' END
  ORDER BY c.party,c.person_name,c.id LIMIT 201
 ) SELECT coalesce(jsonb_agg(to_jsonb(rows)),'[]'::jsonb) FROM rows;
$function$;
CREATE OR REPLACE FUNCTION public.election_history_issue_rows()
RETURNS TABLE(entity text,record_id uuid,period_id uuid,period_number integer,period_name text,label text,issue_code text,issue_label text,list_id uuid)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
BEGIN
 IF NOT public.is_superadmin(auth.uid()) THEN RAISE EXCEPTION 'Nur Super-Admins dürfen Problemfälle öffnen' USING ERRCODE='42501'; END IF;
 RETURN QUERY
 WITH period_issues AS (
  SELECT p.*,i.code,i.title FROM public.election_history_periods p CROSS JOIN LATERAL(VALUES
   ('source_missing','Quelle fehlt',nullif(btrim(p.source_url),'') IS NULL),
   ('election_date_missing','Wahltag fehlt',p.election_date IS NULL),
   ('start_missing','Beginn fehlt',p.starts_on IS NULL),
   ('end_missing','Ende fehlt',p.ends_on IS NULL AND NOT p.is_current AND p.expected_ends_on IS NULL)
  )i(code,title,active) WHERE i.active
 ), mandate_issues AS (
  SELECT m.*,i.code,i.title FROM public.election_history_mandates m JOIN public.election_history_periods p ON p.id=m.period_id
  CROSS JOIN LATERAL(VALUES
   ('source_missing','Quelle fehlt',nullif(btrim(m.source_url),'') IS NULL),
   ('identity_missing','Personenverbindung offen',m.person_id IS NULL AND m.connection_id IS NULL),
   ('district_missing','Direktmandat ohne Wahlkreis',m.mandate_type='direct' AND m.district_id IS NULL),
   ('succession_date_missing','Nachrücker ohne eigenes Eintrittsdatum',m.entry_type='succession' AND (m.starts_on IS NULL OR m.start_from_period)),
   ('start_missing','Beginn fehlt',m.starts_on IS NULL AND m.entry_type<>'succession'),
   ('end_missing','Ende fehlt',m.ends_on IS NULL AND (m.left_early OR p.ends_on IS NOT NULL))
  )i(code,title,active) WHERE i.active
 ), district_issues AS (
  SELECT d.*,i.code,i.title FROM public.election_history_districts d CROSS JOIN LATERAL(VALUES
   ('source_missing','Quelle fehlt',nullif(btrim(d.source_url),'') IS NULL),
   ('direct_missing','Kein Direktmandat zugeordnet',NOT EXISTS(SELECT 1 FROM public.election_history_mandates m WHERE m.period_id=d.period_id AND m.district_id=d.id AND m.mandate_type='direct'))
  )i(code,title,active) WHERE i.active
 ), candidate_issues AS (
  SELECT c.*,i.code,i.title FROM public.election_history_candidacies c CROSS JOIN LATERAL(VALUES
   ('source_missing','Quelle fehlt',nullif(btrim(c.source_url),'') IS NULL),
   ('result_missing','Ergebnis fehlt',c.votes IS NULL AND c.vote_share IS NULL),
   ('outcome_missing','Wahlausgang offen',c.outcome='unknown')
  )i(code,title,active) WHERE i.active
 )
 SELECT 'periods',p.id,p.id,p.number,p.name,p.name,p.code,p.title,NULL::uuid FROM period_issues p
 UNION ALL SELECT 'mandates',m.id,p.id,p.number,p.name,coalesce(m.person_name,person.name,'Name fehlt')||' · '||m.party,m.code,m.title,NULL::uuid FROM mandate_issues m JOIN public.election_history_periods p ON p.id=m.period_id LEFT JOIN public.election_history_people person ON person.id=m.person_id
 UNION ALL SELECT 'districts',d.id,p.id,p.number,p.name,coalesce(d.number_label,d.district_number::text,'–')||': '||d.name,d.code,d.title,NULL::uuid FROM district_issues d JOIN public.election_history_periods p ON p.id=d.period_id
 UNION ALL SELECT 'candidacies',c.id,p.id,p.number,p.name,person.name||' · '||c.party,c.code,c.title,NULL::uuid FROM candidate_issues c JOIN public.election_history_periods p ON p.id=c.period_id JOIN public.election_history_people person ON person.id=c.person_id
 UNION ALL SELECT 'districts',NULL::uuid,p.id,p.number,p.name,p.name,'records_missing','Keine Wahlkreise erfasst',NULL::uuid FROM public.election_history_periods p WHERE NOT EXISTS(SELECT 1 FROM public.election_history_districts d WHERE d.period_id=p.id)
 UNION ALL SELECT 'mandates',NULL::uuid,p.id,p.number,p.name,p.name,'records_missing','Keine Mandate erfasst',NULL::uuid FROM public.election_history_periods p WHERE NOT EXISTS(SELECT 1 FROM public.election_history_mandates m WHERE m.period_id=p.id)
 UNION ALL SELECT 'candidacies',NULL::uuid,p.id,p.number,p.name,p.name,'records_missing','Keine Kandidaturen erfasst',NULL::uuid FROM public.election_history_periods p WHERE NOT EXISTS(SELECT 1 FROM public.election_history_candidacies c WHERE c.period_id=p.id)
 UNION ALL SELECT 'state_lists',NULL::uuid,p.id,p.number,p.name,p.name,'records_missing','Keine Landeslisten erfasst',NULL::uuid FROM public.election_history_periods p WHERE p.number>=18 AND NOT EXISTS(SELECT 1 FROM public.election_history_state_lists l WHERE l.period_id=p.id)
 UNION ALL SELECT 'state_lists',l.id,p.id,p.number,p.name,l.party,'source_missing','Quelle fehlt',l.id FROM public.election_history_state_lists l JOIN public.election_history_periods p ON p.id=l.period_id WHERE nullif(btrim(l.source_url),'') IS NULL
 UNION ALL SELECT 'state_lists',l.id,p.id,p.number,p.name,l.party,'records_missing','Landesliste ohne Einträge',l.id FROM public.election_history_state_lists l JOIN public.election_history_periods p ON p.id=l.period_id WHERE NOT EXISTS(SELECT 1 FROM public.election_history_state_list_entries e WHERE e.list_id=l.id)
 UNION ALL SELECT 'state_lists',e.id,p.id,p.number,p.name,e.position::text||'. '||e.person_name||' · '||l.party,'identity_missing','Personenverbindung offen',l.id FROM public.election_history_state_list_entries e JOIN public.election_history_state_lists l ON l.id=e.list_id JOIN public.election_history_periods p ON p.id=l.period_id WHERE e.connection_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.election_history_mandates m WHERE m.connection_id=e.connection_id)
 UNION ALL SELECT 'candidacies',a.candidacy_id,p.id,p.number,p.name,
  concat_ws(' · ',a.source_data->>'name',a.source_data->>'party',a.source_data->>'district'),
  CASE WHEN a.status='existing_result_differs' THEN 'workbook_candidate_result' ELSE 'workbook_candidate_review' END,
  CASE WHEN a.status='existing_result_differs' THEN 'Persönliches Ergebnis weicht von der Arbeitsmappe ab'
       ELSE 'Arbeitsmappe: '||a.status END,
  NULL::uuid
 FROM public.election_history_candidate_workbook_audit a
 JOIN public.election_history_periods p ON p.number=(a.source_data->>'period')::integer
  AND p.election_year=(a.source_data->>'year')::integer
 WHERE a.status NOT IN ('added','existing');
END $$;
COMMIT;
